public void convert(List<String> tokens) {
        for (String token : tokens) {
            String[] parts = token.split(" ");
            String output = "";
            for (String part : parts) {
                if (part.startsWith(":")) {
                    output += part.substring(1) + " ";
                } else if (part.startsWith("`")) {
                    output += part.substring(1).trim() + " ";
                }
            }
            System.out.print(output.trim() + " ");
        }
    }
}

