public String format(LoggingEvent event){

    if(event == null)
        throw new IllegalArgumentException("Event cannot be null");

    // Initialize Buffer
    StringBuilder buffer = new StringBuilder();

    // Add timestamp
    buffer.append(System.currentTimeMillis());

    // Add severity
    buffer.append(' | ').append(event.getLevel().getName());

    // Add source class name
    buffer.append(' | ').append(event.getLocationInformation().getClassName());

    // Add source method name
    buffer.append(' | ').append(event.getLocationInformation().getMethodName());

    // Add line number
    buffer.append(' | ').append(event.getLocationInformation().getLineNumber());

    // Add message
    buffer.append(' | ').append(event.getMessage().toString());

    // Add exception if available
    if(event.getThrowableInformation() != null)
        buffer.append(' | ').append(ExceptionUtils.getStackTrace(event.getThrowableInformation().getThrowable()));

    // Format the buffer
    buffer.append('\n');

    return buffer.toString();
}

public String format(LoggingEvent event, boolean extension) {
    StringBuffer sbuf = new StringBuffer();

    // Extension point for custom formatting
    if (extension) {
        String customFormat = event.getMDC("customFormat");
        if (customFormat != null) {
            sbuf.append(customFormat);
        }
    }

    // Default formatting
    sbuf.append("[").append(event.getLevel().toString()).append("] [");
    sbuf.append(event.getLoggerName()).append("] ").append(event.getFormattedMessage());
    sbuf.append("\n");

    return sbuf.toString();
}

