private int parseEndOfLine(String headerPart, int end) {
    int index = -1;
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            index = i;
            break;
        }
    }
    return index;
}

private int parseEndOfLine(String headerPart, int end) {
    int lineEnd;
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\n') {
            lineEnd = i;
            break;
        }
    }
    return lineEnd;
}

private int parseEndOfLine(String headerPart,int end) {
    // Check if the index is within the bounds of the header part
    if (end < headerPart.length()) {
        // Check if the character at the current index is a \r or \n
        if (headerPart.charAt(end) == '\r' || headerPart.charAt(end) == '\n') {
            // If the character is a \r or \n, return the current index
            return end;
        } else {
            // If the character is not a \r or \n, increment the index and repeat the process
            return parseEndOfLine(headerPart, end + 1);
        }
    } else {
        // If the index is out of bounds, return -1
        return -1;
    }
}

private int parseEndOfLine(String headerPart, int end) {
 int currentIndex = end;

 while (currentIndex < headerPart.length() && !headerPart.startsWith("\r\n", currentIndex)) {
  currentIndex++;
 }

 if (currentIndex == headerPart.length()) {
  throw new IOException("Reached end of header without finding end of line");
 }

 return currentIndex;
}

int parseEndOfLine(String headerPart, int end) {

    // Loop through each character of the headerPart
    for (int i = 0; i < headerPart.length(); i++) {

        // Check if the current character is a carriage return (\r)
        if (headerPart.charAt(i) == '\r') {

            // Check if the next character is a line feed (\n)
            if (i + 1 < headerPart.length() && headerPart.charAt(i + 1) == '\n') {
                return i + 1;
            }
        }
    }

    // If the end of line was not found, return the end index
    return end;
}

