protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long split = duration / FETCH_DATA_DURATION;
        for (int i = 0; i < split; i++) {
            long startTime = start + i * FETCH_DATA_DURATION;
            long endTime = startTime + FETCH_DATA_DURATION;
            timeRanges.add(new TimeRange(startTime, endTime));
        }
    }
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (end - start > FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, start + FETCH_DATA_DURATION));
        start += FETCH_DATA_DURATION;
    }
    timeRanges.add(new TimeRange(start, end));
    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
   List<TimeRange> timeRanges = new ArrayList<>();
   if (start > end) {
       throw new IllegalArgumentException("start time must be before end time");
   }
   if (end - start > FETCH_DATA_DURATION) {
       long numIntervals = (end - start) / FETCH_DATA_DURATION;
       for (int i = 0; i <= numIntervals; i++) {
           long intervalStart = start + i * FETCH_DATA_DURATION;
           long intervalEnd = intervalStart + FETCH_DATA_DURATION;
           if (intervalEnd > end) {
               intervalEnd = end;
           }
           timeRanges.add(new TimeRange(intervalStart, intervalEnd));
       }
   } else {
       timeRanges.add(new TimeRange(start, end));
   }
   return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
	List<TimeRange> ranges = new ArrayList<>();
	while (start < end) {
		long newEnd = Math.min(start + FETCH_DATA_DURATION - 1, end);
		ranges.add(new TimeRange(start, newEnd));
	}
	return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long duration = Math.min(FETCH_DATA_DURATION, end - start);
        timeRanges.add(new TimeRange(start, start + duration));
        start += duration;
    }
    return timeRanges;
}

