public static long compressTimeBucket(long timeBucket, int dayStep) {
  long result = timeBucket;
  if (dayStep > 1) {
    int dayOfMonth = (int) (timeBucket % 100);
    if (dayOfMonth > dayStep) {
      result -= dayOfMonth - dayStep;
    }
  }
  return result;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 0) {
        throw new IllegalArgumentException("Time bucket cannot be negative");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Day step must be positive");
    }
    long days = (timeBucket / dayStep) * dayStep + (dayStep / 2);
    return days;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Re-format the time bucket long value based on the dayStep
    long reformattedBucket = timeBucket;
    int daysToAdd = dayStep - 1;
    if (daysToAdd > 0) {
        LocalDateTime localDateTime = Instant.ofEpochMilli(timeBucket * 1000L).atZone(ZoneId.systemDefault()).toLocalDateTime();
        LocalDateTime newDateTime = localDateTime.plusDays(daysToAdd);
        Instant newInstant = newDateTime.atZone(ZoneId.systemDefault()).toInstant();
        reformattedBucket = newInstant.toEpochMilli() / 1000L;
    }
    return reformattedBucket;
}

public static long compressTimeBucket(long timeBucket,int dayStep) {
    if (timeBucket == 0) {
        return 0;
    }
    if (dayStep == 1) {
        return timeBucket;
    }
    long dayStepLong = dayStep;
    while (dayStepLong < timeBucket) {
        dayStepLong += dayStep;
    }
    return dayStepLong - dayStep;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {
    long result = timeBucket;
    if (dayStep > 0) {
        long days = TimeUnit.DAYS.convert(timeBucket, TimeUnit.MILLISECONDS);
        long daysToAdd = (days / dayStep) * dayStep;
        result = TimeUnit.MILLISECONDS.convert(daysToAdd, TimeUnit.DAYS);
    }
    return result;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
  // Check if the string is null or empty
  if (str == null || str.length() == 0) {
    return 0;
  }

  // Check if the index is within the bounds of the string
  if (index < 0 || index >= str.length()) {
    throw new IndexException("Index out of bounds");
  }

  // Check if the length is non-negative
  if (len < 0) {
    throw new IllegalArgumentException("Length cannot be negative");
  }

  int length = 0;
  int i = index;
  int lastChar = index + len;
  while (i < lastChar) {
    char c = str.charAt(i);
    i++;
    if (c >= 0x01 && c <= 0x7F) {
      length++;
    } else if (c >= 0xC2 && c <= 0xDF) {
      length += 2;
    } else if (c >= 0xE0 && c <= 0xEF) {
      length += 3;
    } else if (c >= 0xF0 && c <= 0xF7) {
      length += 4;
    } else {
      length++;
    }
  }

  return length;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        size += c <= 0x7F ? 1 : c <= 0x7FF ? 2 : c <= 0xFFFF ? 3 : 4;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null || str.length() == 0 || index < 0 || len <= 0) {
        return 0;
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
        } else if (c <= 0x7FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }

    return size;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        throw new NullPointerException("The str argument must not be null.");
    }
    if (index < 0 || index >= str.length()) {
        throw new IllegalArgumentException("The index argument must be between 0 and the length of the str argument.");
    }
    if (len < 0) {
        throw new IllegalArgumentException("The length argument must not be negative.");
    }
    if (len + index > str.length()) {
        throw new IllegalArgumentException("The length argument must not exceed the length of the str argument.");
    }

    int size = 0;
    for (int pos = index; pos < len; pos++) {
        char c = str.charAt(pos);
        if (c <= 0x007F) {
            size += 1;
        } else if (c <= 0x07FF) {
            size += 2;
        } else if (c <= 0xFFFF) {
            size += 3;
        } else if (c <= 0x10FFFF) {
            size += 4;
        }
    }

    return size;
}

