        for (int i = 0; i < byteLength; i++) {
            expand();
            data[index++] = 0;
        }
        return this;
    }

    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("Index: " + byteOffset + ", Size: " + byteArrayValue.length);
    }

    // adjust the length to ensure that the new bytes can fit in the byte vector
    int newLength = Math.max(byteLength, length + (byteOffset + byteLength) - capacity);
    ensureCapacity(newLength);

    // copy the array into the byte vector
    for (int i = byteOffset, j = 0; j < byteLength; j++) {
        expand();
        data[index++] = byteArrayValue[i++];
    }
    return this;
}

