public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null) {
        throw new IllegalArgumentException("Str cannot be null");
    }
    if (session == null) {
        throw new IllegalArgumentException("WriteSession cannot be null");
    }
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    // Determine the number of bytes needed to encode the string
    int byteCount = 0;
    for (int i = 0; i < str.length(); i++) {
        byteCount += UTF8.getByteCount(str.charAt(i));
    }
    // Allocate a buffer of the appropriate size
    lb.allocate(byteCount);
    // Write the string into the buffer
    for (int i = 0; i < str.length(); i++) {
        lb.writeUTF8(str.charAt(i));
    }
    return lb;
}

