    for (int i = 0; i < len; i++) {
        final char c = str.charAt(i);
        if (c < 0x80) {
            //write the byte as-is
            lb.writeByte((byte)c);
        } else if (c < 0x800) {
            //write the byte as two bytes
            lb.writeByte((byte)(0xC0 | ((c >> 6) & 0x1F)));
            lb.writeByte((byte)(0x80 | (c & 0x3F)));
        } else {
            //write the byte as three bytes
            lb.writeByte((byte)(0xE0 | ((c >> 12) & 0x0F)));
            lb.writeByte((byte)(0x80 | ((c >> 6) & 0x3F)));
            lb.writeByte((byte)(0x80 | (c & 0x3F)));
        }
    }

    return lb;
}

