public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  List<PathSegmentImpl> pathSegments = new ArrayList<>();
  String path = u.getRawPath();
  if (path == null) {
    return Collections.emptyList();
  }
  StringBuilder currentSegment = new StringBuilder();
  boolean startSegment = true;
  for (int i = 0; i < path.length(); i++) {
    char c = path.charAt(i);
    if (c == '/') {
      if (currentSegment.length() > 0 || !startSegment) {
        PathSegmentImpl segment = new PathSegmentImpl(currentSegment.toString(), decode);
        pathSegments.add(segment);
        currentSegment.setLength(0);
      }
      startSegment = true;
    } else {
      currentSegment.append(c);
      startSegment = false;
    }
  }
  if (currentSegment.length() > 0 || !startSegment) {
    PathSegmentImpl segment = new PathSegmentImpl(currentSegment.toString(), decode);
    pathSegments.add(segment);
  }
  return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u,boolean decode){
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    String pathComponent = u.getRawPath();
    if(pathComponent == null){
        return pathSegments;
    }
    if(decode){
        try{
            pathComponent = URLDecoder.decode(pathComponent, "UTF-8");
        }catch (UnsupportedEncodingException e) {
            throw new RuntimeException(e);
        }
    }

    int startIndex = 0;
    int endIndex = 0;
    int segmentCount = 0;
    int lastSlash = pathComponent.lastIndexOf('/');

    if(lastSlash != -1){
        startIndex = lastSlash + 1;
    }
    while(true){
        endIndex = pathComponent.indexOf('/', startIndex);
        if(endIndex == -1){
        String segment = pathComponent.substring(startIndex, pathComponent.length);
            if(decode){
                try{
                    segment = URLDecoder.decode(segment, "UTF-8");
                }catch(UnsupportedEncodingException e){
                    throw new RuntimeException(e);
                }
            }
            pathSegments.add(new PathSegmentImpl(segment, 0));
            break;
        }
        String segment = pathComponent.substring(startIndex, endIndex);
        if(decode){
            try {
                segment = URLDecoder.decode(segment, "UTF-8");
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException(e);
            }
        }
        pathSegments.add(new PathSegmentImpl(segment, 0));
        startIndex = endIndex + 1;
    }

    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    String path = u.getPath();
    int offset = 0;
    if (u.getPath().startsWith("/")) {
        offset = 1;
    }
    for (int i = offset; i < path.length(); i++) {
        char c = path.charAt(i);
        if (c == '/') {
            int nextOffset = i + 1;
            if (nextOffset >= path.length()) {
                break;
            }
            String segment = path.substring(offset, i);
            if (segment.length() > 0 || segments.size() > 0) {
                segments.add(new PathSegmentImpl(decode ? URLDecoder.decode(segment) : segment));
            }
            offset = nextOffset;
        }
    }
    if (offset < path.length()) {
        String segment = path.substring(offset);
        if (segment.length() > 0 || segments.size() > 0) {
            segments.add(new PathSegmentImpl(decode ? URLDecoder.decode(segment) : segment));
        }
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
	List<PathSegmentImpl> pathSegments = new ArrayList<>();
	String[] segments = u.getPath().split("/");
	String firstSegment = "";
	if (u.isAbsolute()) {
		firstSegment = segments[0];
		segments = Arrays.copyOfRange(segments, 1, segments.length);
	}
	for (String segment : segments) {
		if (decode) {
			segment = URLDecoder.decode(segment, "UTF-8");
		}
		pathSegments.add(new PathSegmentImpl(segment));
	}
	if (u.isAbsolute()) {
		pathSegments.add(new PathSegmentImpl(firstSegment));
	}
	return pathSegments;
}

