@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return value;
        } else if (value instanceof String) {
            final String stringValue = (String) value;
            if (stringValue.length() == 1) {
                return Character.valueOf(stringValue.charAt(0));
            } else {
                throw new Exception("Failed to convert value '" + value + "' to type '" + type + "': cannot convert string of length > 1 to char.");
            }
        } else if (value instanceof Number) {
            final Number numberValue = (Number) value;
            if (numberValue.intValue() >= 0 && numberValue.intValue() <= Character.MAX_VALUE) {
                return Character.valueOf((char) numberValue.intValue());
            } else {
                throw new Exception("Failed to convert value '" + value + "' to type '" + type + "': overflow or underflow.");
            }
        } else {
            throw new Exception("Failed to convert value '" + value + "' to type '" + type + "': unsupported type.");
        }
    } else {
        throw new Exception("Failed to convert value '" + value + "' to type '" + type + "': unsupported type.");
    }
}

