public static int nextPrime(int desiredCapacity) {

    if (desiredCapacity < 11) {
        return 11;
    }

    int prime = 13;
    while (true) {
        if (prime > desiredCapacity) {
            break;
        }

        prime += 2;
    }

    return prime;
}

