    // Check if the desired capacity is a prime number
    if (isPrime(desiredCapacity)) {
        return desiredCapacity;
    }

    // Find the next prime number that is >= desiredCapacity
    int prime = desiredCapacity;
    while (!isPrime(prime)) {
        prime++;
    }
