public static String unescapeJava(String str) throws Exception {
	if (str == null) {
		return null;
	}

	StringBuilder result = new StringBuilder(str.length());
	boolean escaped = false;

	for (int i = 0; i < str.length(); i++) {
		char c = str.charAt(i);

		if (escaped) {
			if (c == 'n') {
				result.append('\n');
			} else if (c == 'r') {
				result.append('\r');
			} else if (c == 't') {
				result.append('\t');
			} else if (c == 'b') {
				result.append('\b');
			} else if (c == 'f') {
				result.append('\f');
			} else if (c == '\"') {
				result.append('\"');
			} else if (c == '\'') {
				result.append('\'');
			} else if (c == '\\') {
				result.append('\\');
			} else if (c == 'u') {
				if (i + 4 < str.length()) {
					char unicode = (char) Integer.parseInt(str.substring(i + 1, i + 5), 16);
					result.append(unicode);
					i += 4;
				} else {
					throw new Exception("Invalid unicode sequence");
				}
			} else {
				throw new Exception("Invalid backslash escape sequence");
			}

			escaped = false;
		} else {
			if (c == '\\') {
				escaped = true;
			} else {
				result.append(c);
			}
		}
	}

	if (escaped) {
		throw new Exception("Invalid backslash escape sequence");
	}

	return result.toString();
}

public static String unescapeJava(String str) {
  if (str == null) {
    return null;
  }
  String result = str.replace("\\n", "\n");
  result = result.replace("\\r", "\r");
  result = result.replace("\\t", "\t");
  result = result.replace("\\b", "\b");
  result = result.replace("\\f", "\f");
  result = result.replace("\\'", "'");
  result = result.replace("\\\"", "\"");
  result = result.replace("\\\\", "\\");
  return result;
}

