private int computeBinaryLog(int n) {
    // Initialize result with -1
    int result = -1;
    // Do while loop till n is greater than 0
    while (n > 0) {
        // Increment result by 1
        result++;
        // Shift n right by 1
        n >>= 1;
    }
    // Return result
    return result;
}

