   // convert the index to a double pointer
   long longConstantPoolIndex = constantPoolEntryIndex;
   long doublePointer = longConstantPoolIndex;

   // read the class file buffer starting from the double pointer
   long length = classFileBuffer.getLong(doublePointer);
   doublePointer += 8;
   int i = 0;
   while (i < length) {
     charBuffer[i] = classFileBuffer.getChar(doublePointer);
     doublePointer += 2;
     i++;
   }

   return new String(charBuffer, 0, i);
  } catch (IndexOutOfBoundsException e) {
    throw new IllegalArgumentException("Invalid constant pool entry index " + constantPoolEntryIndex, e);
  }
}

