    // check if the buffer is large enough
    if (charBuffer.length < 2) {
        throw new IllegalArgumentException("charBuffer must have length >= 2");
    }
    // check if the constant pool entry index is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length - 3) {
        throw new IllegalArgumentException("constantPoolEntryIndex out of bounds");
    }
    // read the string length
    int stringLength = classFileBuffer.getUnsignedShort(constantPoolEntryIndex);
    // check if the string length is valid
    if (stringLength < 1 || stringLength > charBuffer.length - 1) {
        throw new IllegalArgumentException("string length out of bounds");
    }
    // read the string bytes
    for (int i = 0; i < stringLength; i++) {
        charBuffer[i] = (char) classFileBuffer.getUnsignedByte(constantPoolEntryIndex + 2 + i);
    }
    return new String(charBuffer, 0, stringLength);
}

