    if (charBuffer.length < 1) {
        throw new IllegalArgumentException("Buffer must be at least 1 character long");
    }

    // Read the length of the string
    numRead = readShort(constantPoolEntryIndex, numRead);

    // Check if the length is valid
    if (numRead < 0) {
        throw new IllegalArgumentException("Invalid length for CONSTANT_Utf8 entry");
    }

    total = numRead - 1;

