private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator result;
    Node node = start;
    while (true) {
        if (node == stop) {
            result = new OuterFaceCirculator(stop, dir);
            break;
        }
        if (predicate.test(node)) {
            result = new OuterFaceCirculator(node, dir);
            break;
        }
        node = node.getNextNodeOnOuterFace(dir);
    }
    return result;
}

protected OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start);
    while (circulator.getNode() != stop) {
        if (predicate.test(circulator.getNode())) {
            return circulator;
        } else {
            circulator.move(dir);
        }
    }
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Perform a breadth-first search of the component starting from the given start node.
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null.");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node cannot be null.");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node cannot be null.");
    }
    if (dir != 0 && dir != 1) {
        throw new IllegalArgumentException("Direction must be 0 or 1.");
    }

    Queue<Node> queue = new LinkedList<>();
    queue.add(start);
    HashMap<Node, Node> visited = new HashMap<>();
    while (!queue.isEmpty()) {
        Node node = queue.poll();
        if (visited.containsKey(node)) {
            continue;
        }
        visited.put(node, node);
        for (int i = 0; i < node.getOutgoingEdgeCount(); i++) {
            Node target = node.getOutgoingEdge(i).getOpposite(node);
            if (!visited.containsKey(target)) {
                visited.put(target, node);
                queue.add(target);
            }
        }
    }

    // Once the BFS has completed, return a circulator to the first node
    // that satisfies the predicate, or to the stop node if no such node exists.
    Node cur = start;
    while (cur != stop && !predicate.test(cur)) {
        cur = visited.get(cur);
    }
    if (cur == stop) {
        return new OuterFaceCirculator(cur, start, stop);
    }
    return new OuterFaceCirculator(cur, visited.get(cur), stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
    while (circulator.getNode() != stop) {
        if (predicate.test(circulator.getNode())) {
            return circulator;
        }
        circulator.moveNext();
    }
    return null;
}

Optional <Node> selectedNode = start.circulate(dir).filter(predicate).findFirst();
return new OuterFaceCirculator(selectedNode.orElse(stop), start);
}

