public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        // Handle null input.
        return this;
    }

    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset out of bounds: " + byteOffset);
    }

    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength out of bounds: " + byteLength);
    }

    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        this.putByte(byteArrayValue[i]);
    }

    return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
  // handle edge cases
  if (byteArrayValue == null) {
    if (byteOffset != 0 || byteLength != 0) {
      throw new IndexOutOfBoundsException("If byteArrayValue is null, byteOffset and byteLength must be 0");
    }
  } else {
    // handle edge cases
    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
      throw new IndexOutOfBoundsException("Invalid byteOffset: " + byteOffset);
    }
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
      throw new IndexOutOfBoundsException("Invalid byteLength: " + byteLength);
    }
  }

  // calculate necessary capacity
  int capacity = this.length + byteLength;

  // resize the buffer if necessary
  if (capacity > this.contents.length) {
    this.resizeBuffer(capacity);
  }

  // copy the byte array into the buffer
  System.arraycopy(byteArrayValue, byteOffset, this.contents, this.length, byteLength);

  // update the length
  this.length += byteLength;

  return this;
}

public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength) throws IllegalArgumentException {
    // Check if the byte array is null
    if (byteArrayValue == null) {
        // Check if byteOffset and byteLength are valid
        if (byteOffset < 0 || byteLength < 0 || byteOffset + byteLength > byteArrayValue.length) {
            throw new IllegalArgumentException("Invalid byteOffset and/or byteLength");
        }
        // Put the null bytes into this byte vector
        for (int i = byteOffset; i < byteOffset + byteLength; i++) {
            putByte(0);
        }
        return this;
    }
    // Put the byte array into this byte vector
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
        putByte(byteArrayValue[i]);
    }
    return this;
}

