public final MatchResult match(CharSequence uri) {
    if (uri == null || uri.length() == 0) {
        return null;
    }
    if (!uri.startsWith("http://") && !uri.startsWith("https://")) {
        return null;
    }
    String[] parts = uri.split("\\/");
    if (parts.length < 3) {
        return null;
    }
    String scheme = parts[0];
    String host = parts[1];
    String path = parts[2];
    if (!scheme.equals("http") && !scheme.equals("https")) {
        return null;
    }
    if (!host.matches("[a-zA-Z0-9\\-\\.]+")) {
        return null;
    }
    if (!path.matches("[a-zA-Z0-9\\-\\.\\/_]+")) {
        return null;
    }
    return new MatchResult(scheme, host, path);
}

public final MatchResult match(CharSequence uri){
  if(uri == null)
  {
    return null;
  }
  int length = uri.length();
  if(length == 0)
  {
    return null;
  }

  int end = pathPattern.matches(uri);
  if(end == 0)
  {
    return null;
  }

  String value = uri.substring(0, end);
  String query = uri.substring(end);
  Map<String, String> parameters = Splitter.on(query).withKeyValueSeparator("=").split(query);
  return new MatchResult(value, parameters);
}

public final MatchResult match(CharSequence uri) {
    // Check if the uri is null or empty
    if (uri == null || uri.length() == 0) {
        return null;
    }

    // Check if the uri starts with the match pattern
    if (!uri.startsWith(matchPattern)) {
        return null;
    }

    // Create a matcher to match the uri against the template
    Matcher matcher = pattern.matcher(uri);

    // Check if the matcher finds a match
    if (!matcher.find()) {
        return null;
    }

    // Create a match result from the matcher
    MatchResult matchResult = new MatchResult();
    matchResult.setMatcher(matcher);
    matchResult.setStartIndex(matcher.start());
    matchResult.setEndIndex(matcher.end());
    matchResult.setGroupCount(matcher.groupCount());

    // Return the match result
    return matchResult;
}

