    double EPSILON = 1e-6;

    // check if the sum of the weights entering a vertex is not 0
    if (v.size() == 0) {
        return 0;
    }

    // calculate the sum of the weights entering a vertex
    double sumWeights = 0;
    for (V v1 : v) {
        sumWeights += v1.getWeight();
    }

    // check if the sum of the weights entering a vertex is not 0
    if (Math.abs(sumWeights) < EPSILON) {
        return 0;
    }

    return sumWeights;
}

