private String parseToken(final char[] terminators) {
    StringBuilder token = new StringBuilder();
    boolean isQuote = false;
    char currentChar;

    while ((currentChar = read()) != -1) {
        // If the current character is a terminator, stop parsing
        for (char terminator : terminators) {
            if (currentChar == terminator) {
                break;
            }
        }

        // If we're in a quote, only stop parsing if we find the matching quote
        if (isQuote && currentChar == '"') {
            isQuote = false;
        } else if (!isQuote && currentChar == '"') {
            isQuote = true;
        }

        if (!isQuote) {
            token.append(currentChar);
        }
    }

    return token.toString();
}

public String parseToken(char[] terminators) {
    // initialization
    String token = "";
    char currentChar;
    boolean endOfToken = false;

    // loop till the end of the input
    while (endOfToken == false) {
        // read the next character
        currentChar = (char) System.in.read();

        // check if the current character is a terminator
        for (char terminator : terminators) {
            if (currentChar == terminator) {
                endOfToken = true;
                break;
            }
        }

        // if the current character is not a terminator, add it to the token
        if (endOfToken == false) {
            token += currentChar;
        }
    }

    // return the parsed token
    return token;
}

