public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0 || from < 0 || to <= 0 || from > to || to >= arr.length) {
        return;
    }
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null || arr.length == 0) {
        return;
    }
    if (from < 0 || to < 0 || from >= arr.length || to >= arr.length) {
        throw new IndexOutOfBoundsException("Invalid range: [" + from + ", " + to + "] for array of length " + arr.length);
    }
    if (from >= to) {
        return;
    }
    int mid = (from + to) / 2;
    for (int i = from; i < mid; i++) {
        V temp = arr[i];
        arr[i] = arr[to - i + from];
        arr[to - i + from] = temp;
    }
}

