private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // check if string is empty
    if (str == null || str.isEmpty()) {
        return prefix == null || prefix.isEmpty();
    }
    // check if prefix is empty
    if (prefix == null || prefix.isEmpty()) {
        return true;
    }
    // check if prefix is longer than the string
    if (prefix.length() > str.length()) {
        return false;
    }
    // check if the string starts with the prefix
    if (ignoreCase) {
        return str.toLowerCase().startsWith(prefix.toLowerCase());
    }
    return str.startsWith(prefix);
}

public static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    if (str == null || prefix == null) {
        return true;
    }
    if (ignoreCase) {
        return str.toLowerCase().startsWith(prefix.toLowerCase());
    } else {
        return str.startsWith(prefix);
    }
}

public boolean startsWith(String str, String prefix, boolean ignoreCase) {
    // Check if str or prefix are null
    if (str == null || prefix == null) {
        return true;
    }
    // Check if prefix is empty
    if (prefix.isEmpty()) {
        return true;
    }
    // Compare the first character of str and prefix
    char firstStrChar = str.charAt(0);
    char firstPrefixChar = prefix.charAt(0);
    if (ignoreCase) {
        return Character.toLowerCase(firstStrChar) == Character.toLowerCase(firstPrefixChar);
    } else {
        return firstStrChar == firstPrefixChar;
    }
}

