public List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph graph){
    // List to store the global separator list
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    // Get a list of all edges in the graph
    List<E> edges = graph.getEdges();

    // Iterate over each edge and compute its minimal separators
    for(E edge : edges){
        List<Pair<Integer,Integer>> minimalSeparators = computeMinimalSeparators(graph, edge);
        globalSeparatorList.add(Pair.of(minimalSeparators, edge));
    }

    return globalSeparatorList;
}

