        buf.setCharAt(i, Character.toUpperCase(c));
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
  boolean isAbbreviable = nameStart > 0;
  int index = nameStart - 1;
  while (isAbbreviable && index >= 0) {
    char currentChar = buf.charAt(index);
    if (!Character.isLetter(currentChar) || currentChar == '.') {
      isAbbreviable = false;
    } else {
      index--;
    }
  }

  if (isAbbreviable) {
    buf.setLength(index + 1);
    buf.append('…');
  }
}

