public static Class<?> resolveBound(TypeVariable<?> typeVariable) {
    // Get the bounds of the type variable
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length == 0) {
        return Unknown.class;
    }
    // Get the first bound
    Type bound = bounds[0];
    if (bound instanceof Class) {
        return (Class<?>) bound;
    } else if (bound instanceof ParameterizedType) {
        return (Class<?>) ((ParameterizedType) bound).getRawType();
    } else {
        return Unknown.class;
    }
}

