    for (V vertex : vertices) {
        for (V otherVertex : vertices) {
            if (vertex != otherVertex && !graph.containsEdge(vertex, otherVertex)) {
                return false;
            }
        }
    }
    return true;
}

public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (vertices.size() <= 1) {
        return true;
    }

    for (V source : vertices) {
        Set<V> neighbors = graph.getNeighbors(source);
        for (V target : vertices) {
            if (!neighbors.contains(target)) {
                return false;
            }
        }
    }

    return true;
}

