public static String applyRelativePath(String path, String relativePath) {
    // First, split the relative path into components
    String[] components = relativePath.split("/");
    // Iterate over the components, parsing each one
    for (String component : components) {
        if (component.equals(".")) {
            // The current directory is a no-op
            continue;
        } else if (component.equals("..")) {
            // Go into the parent directory
            // If the path is empty, this is an illegal path
            if (path.isEmpty()) {
                throw new IllegalArgumentException("Illegal path: " + path);
            }
            // Find the last separator in the path
            int lastSeparator = path.lastIndexOf("/");
            // If there is no separator, the path is a single file name and cannot have a parent
            if (lastSeparator < 0) {
                throw new IllegalArgumentException("Illegal path: " + path);
            }
            // Remove everything after the last separator
            path = path.substring(0, lastSeparator);
        } else {
            // This is a file or directory name, so add it to the path
            if (!path.isEmpty() && !path.endsWith("/")) {
                path += "/";
            }
            path += component;
        }
    }
    return path;
}

