public static String applyRelativePath(String path, String relativePath) {
  // Validate input
  if (path == null || path.isEmpty()) {
    throw new IllegalArgumentException("Path cannot be null or empty");
  }
  if (relativePath == null || relativePath.isEmpty()) {
    throw new IllegalArgumentException("Relative path cannot be null or empty");
  }

  // Remove any leading or trailing slashes from the path and relative path
  path = path.trim().replaceAll("^/*", "").replaceAll("/*$", "");
  relativePath = relativePath.trim().replaceAll("^/*", "").replaceAll("/*$", "");

  // Split the path and relative path into arrays of directories
  String[] pathArray = path.split("/");
  String[] relativePathArray = relativePath.split("/");

  // Iterate through the relative path array and determine the new absolute path
  String newPath = path;
  for (String relativePathPart : relativePathArray) {
    if (relativePathPart.equals("..")) {
      // If the relative path part is "..", we need to remove the last directory from the new path
      int lastSlashIndex = newPath.lastIndexOf("/");
      if (lastSlashIndex > 0) {
        newPath = newPath.substring(0, lastSlashIndex);
      }
    } else {
      // Otherwise, we can just append the relative path part to the new path
      if (!newPath.isEmpty()) {
        newPath += "/";
      }
      newPath += relativePathPart;
    }
  }

  return newPath;
}

