    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line = reader.readLine();
        while (line != null) {
            long timestamp = Long.parseLong(line);
            ThreadSnapshot snapshot = new ThreadSnapshot(timestamp);
            line = reader.readLine();
            while (line != null && line.startsWith("    ")) {
                String[] split = line.split("\\|");
                String threadId = split[1];
                long cpuTime = Long.parseLong(split[2]);
                long waitTime = Long.parseLong(split[3]);
                int state = Integer.parseInt(split[4]);
                snapshot.addThreadInfo(threadId, cpuTime, waitTime, state);
                line = reader.readLine();
            }
            snapshots.add(snapshot);
            // Check if the snapshot falls within the time range
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (snapshot.getTimestamp() >= timeRange.getStart() && snapshot.getTimestamp() <= timeRange.getEnd()) {
